const cp = require('child_process'); const fs = require('fs');
const fail = (m) => { console.log(m); process.exit(1); };
let sm;
try { cp.execFileSync('rojo', ['sourcemap', 'default.project.json', '-o', 'sourcemap.json', '--include-non-scripts'], { stdio: 'pipe' }); sm = JSON.parse(fs.readFileSync('sourcemap.json', 'utf8')); } catch (e) { fail('rojo sourcemap failed: ' + String((e.stderr && e.stderr.toString()) || e.message).replace(/[A-Za-z]:[\\/][^\s]*[\\/]/g, '').slice(0, 400)); }
const kids = (n, name) => (n && n.children ? n.children : []).filter((c) => c.name === name);
const child = (n, name) => kids(n, name)[0];
const isPkg = (n) => /roblox_packages/.test((n.filePaths || []).join(' ')) || n.name === '.pesde';
const walk = (n, fn, p) => { if (!n) return; const here = (p ? p + '.' : '') + n.name; fn(n, here); for (const c of n.children || []) if (!isPkg(c)) walk(c, fn, here); };
const rel = (f) => { const s = f.replace(/\\/g, '/'); const i = s.indexOf('src/'); return i >= 0 ? s.slice(i) : s; };
const rs = child(sm, 'ReplicatedStorage'); const mod = child(child(rs, 'Rules'), 'BlockRules');
if (!mod) fail('ReplicatedStorage.Rules.BlockRules is not in the place built from default.project.json');
if (mod.className !== 'ModuleScript') fail('ReplicatedStorage.Rules.BlockRules is a ' + mod.className + ', not a ModuleScript');
const meta = (mod.filePaths || []).find((f) => f.endsWith('.meta.json'));
if (!meta) fail('BlockRules has no .meta.json, so its MaxReach and MaxHeight attributes are gone');
const attrs = JSON.parse(fs.readFileSync(meta, 'utf8').replace(/^﻿/, '')).attributes || {};
if (attrs.MaxReach !== 24 || attrs.MaxHeight !== 200) fail('BlockRules attributes are ' + JSON.stringify(attrs));
const left = []; walk(sm, (n, p) => { if (n.name === 'PlacementRules') left.push(p); });
if (left.length) fail('PlacementRules is still in the place at ' + left.join(', '));
console.log('ReplicatedStorage.Rules.BlockRules is a ModuleScript with MaxReach 24 and MaxHeight 200 from ' + rel(meta) + ', and no PlacementRules instance is left');

const fs = require('fs'); const path = require('path'); const hits = [];
const scan = (d) => { if (!fs.existsSync(d)) return; for (const e of fs.readdirSync(d, { withFileTypes: true })) { const p = path.join(d, e.name); if (e.isDirectory()) scan(p); else if (/\.(luau|lua|md|json)$/.test(e.name) && /(?<!Specs[.\/])Placement[.\/]PlacementRules/.test(fs.readFileSync(p, 'utf8'))) hits.push(p.replace(/\\/g, '/')); } };
scan('src'); scan('docs');
if (hits.length) { console.log('the old Placement.PlacementRules path is still referenced in ' + hits.join(', ')); process.exit(1); }
console.log('no file under src or docs refers to the old Placement.PlacementRules path (spec paths under Specs/Placement are allowed)');
